ZERO = (0, 0, 0)


def const(value):
    return {} if not value else {ZERO: value}


def add(a, b):
    out = dict(a)
    for powers, coefficient in b.items():
        value = h.add(out.get(powers, {}), coefficient)
        if value:
            out[powers] = value
        else:
            out.pop(powers, None)
    return out


def smul(a, value):
    out = {powers: h.mul(coefficient, value) for powers, coefficient in a.items()}
    return {powers: coefficient for powers, coefficient in out.items() if coefficient}


def mul(a, b):
    out = {}
    for pa, ca in a.items():
        for pb, cb in b.items():
            powers = tuple(x + y for x, y in zip(pa, pb))
            out = add(out, {powers: h.mul(ca, cb)})
    return out


def power(a, n):
    out = const(h.scalar(1))
    for _ in range(n):
        out = mul(out, a)
    return out


def deriv(a, coordinate):
    out = {}
    for powers, coefficient in a.items():
        if powers[coordinate]:
            updated = list(powers)
            updated[coordinate] -= 1
            out = add(out, {tuple(updated): h.scale(coefficient, powers[coordinate])})
    return out


def conjugate(a):
    return {powers: h.conj(coefficient) for powers, coefficient in a.items()}


def total(values):
    out = {}
    for value in values:
        out = add(out, value)
    return out


def parse_node(node):
    if isinstance(node, ast.Name) and node.id in ('x', 'y', 'z'):
        return {tuple(int(name == node.id) for name in ('x', 'y', 'z')): h.scalar(1)}
    if isinstance(node, ast.Name) and node.id == 'I':
        return const({(1, 1): Q(1)})
    if isinstance(node, ast.Constant) and type(node.value) is int:
        return const(h.scalar(node.value))
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
        return smul(parse_node(node.operand), h.scalar(-1 if isinstance(node.op, ast.USub) else 1))
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == 'sqrt':
        if len(node.args) != 1 or node.keywords or not isinstance(node.args[0], ast.Constant) or type(node.args[0].value) is not int:
            raise ValueError('Expected an integer square root')
        return const(h.radical(node.args[0].value))
    if not isinstance(node, ast.BinOp):
        raise ValueError('Outside the exact polynomial grammar')
    if isinstance(node.op, ast.Pow):
        if not isinstance(node.right, ast.Constant) or type(node.right.value) is not int or node.right.value < 0:
            raise ValueError('Expected nonnegative integer power')
        return power(parse_node(node.left), node.right.value)
    a, b = parse_node(node.left), parse_node(node.right)
    if isinstance(node.op, ast.Add):
        return add(a, b)
    if isinstance(node.op, ast.Sub):
        return add(a, smul(b, h.scalar(-1)))
    if isinstance(node.op, ast.Mult):
        return mul(a, b)
    if isinstance(node.op, ast.Div) and set(b) == {ZERO} and set(b[ZERO]) == {(1, 0)}:
        return smul(a, h.scalar(1 / b[ZERO][(1, 0)]))
    raise ValueError('Unexpected polynomial operation')


def parse(text):
    return parse_node(ast.parse(text, mode='eval').body)


def value_at(poly, point):
    out = {}
    for powers, coefficient in poly.items():
        factor = Q(1)
        for coordinate, exponent in zip(point, powers):
            factor *= coordinate ** exponent
        out = h.add(out, h.scale(coefficient, factor))
    return out


def dfactorial(n):
    value = 1
    for item in range(n, 0, -2):
        value *= item
    return value


