                for q in (-1, 1):
                    result = d_inner(L, LP, m, q)
                    expected = scalar(Q(1, 2 * L + 1) if L == LP else 0)
                    key = f'L{L}_LP{LP}_m{m}_q{q}'
                    angular.append({'key': key, 'independent_factorial_integral_matches': result == expected,
                                    'matches_saved_exact_value': result == parse(control['full_sphere_d_integrals'][key])})
    VR = [[parse(value) for value in row] for row in control['V_R_E1']]
    VO = [[parse(value) for value in row] for row in control['V_O_M2']]
    initial = [Q(value) for value in control['initial_M_order']]
    final = Q(-1, 2), Q(1, 2)
    source_norm = []
    for L in (1, 2):
        for Mi in initial:
            value = sum_scalar(mul(cg(Q(1, 2), L, Q(3, 2), Mf, Mi - Mf, Mi),
                                  cg(Q(1, 2), L, Q(3, 2), Mf, Mi - Mf, Mi)) for Mf in final)
            source_norm.append({'L': L, 'Mi': str(Mi), 'norm_is_one': value == scalar(1)})
    rho = [[parse(value) for value in row] for row in control['complex_PSD_initial_density_control']]
    psi = [scalar(1), {(1, 1): Q(1)}, scalar(Q(1, 2)), {(1, 1): Q(-1, 3)}]
    pure = [[scale(mul(a, conj(b)), Q(36, 85)) for b in psi] for a in psi]
    rho_constructed = ma(ms(pure, Q(2, 3)), ms(eye(4), Q(1, 12)))
    e, t = Q(9, 25), Q(12, 25)
